ALTER TABLE public.schools ADD COLUMN trial_started_at timestamptz, ADD COLUMN trial_expires_at timestamptz, ADD COLUMN trial_converted_at timestamptz;
CREATE TABLE public.trial_registrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_email text NOT NULL UNIQUE, admin_email text NOT NULL UNIQUE, payload jsonb NOT NULL, school_id uuid, user_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.trial_registrations TO service_role;
ALTER TABLE public.trial_registrations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.trial_registration_limits (key text PRIMARY KEY, window_started_at timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0);
GRANT ALL ON public.trial_registration_limits TO service_role;
ALTER TABLE public.trial_registration_limits ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.trial_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE, milestone integer NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,milestone));
GRANT SELECT ON public.trial_notifications TO authenticated;
GRANT ALL ON public.trial_notifications TO service_role;
ALTER TABLE public.trial_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY trial_notification_read ON public.trial_notifications FOR SELECT TO authenticated USING (public.is_super_admin(auth.uid()) OR public.is_school_admin(auth.uid(),school_id));
CREATE TABLE public.subscription_upgrade_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE, requested_by uuid NOT NULL, plan public.subscription_plan NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.subscription_upgrade_requests TO authenticated;
GRANT ALL ON public.subscription_upgrade_requests TO service_role;
ALTER TABLE public.subscription_upgrade_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY upgrade_request_read ON public.subscription_upgrade_requests FOR SELECT TO authenticated USING (public.is_super_admin(auth.uid()) OR public.is_school_admin(auth.uid(),school_id));
CREATE POLICY upgrade_request_insert ON public.subscription_upgrade_requests FOR INSERT TO authenticated WITH CHECK (public.is_school_admin(auth.uid(),school_id) AND requested_by=auth.uid() AND status='pending');
CREATE UNIQUE INDEX one_pending_upgrade_per_school ON public.subscription_upgrade_requests(school_id) WHERE status='pending';